# Converted to the revised ten-section template (plus section 11); content and tables carried from the previous version.
BOOK = '1 Chronicles'
TESTAMENT = 'Old Testament'
GENRE = 'history'
SUBTITLE = 'Israel’s Line, David’s Throne, and the House of the LORD'
SECTIONS = [(1, 'Book Setting & Program Identity', [('p', 'This section introduces you to the book by explaining who wrote it, who received it, and what was happening when it was written. It also shows you which of God’s programs the book belongs to — Israel’s prophetic program or the Body of Christ’s mystery program. Knowing the setting and the program identity helps you read the book in its proper context and understand how its teachings fit into the larger story of Scripture.'), ('p', '1 Chronicles retells Israel’s history to reaffirm God’s covenant faithfulness, Davidic kingship, and Temple-centered worship for a post-exilic Israel struggling with identity and hope (1 Chr. 16:15–17; 2 Sam. 7:12–16). The audience is returning Jewish exiles in the Persian period (Ezra 1:1–5). The book was written after the Babylonian exile, during the rebuilding of Israel’s national and worship life (2 Chr. 36:22–23).'), ('box', 'Program Identity:', 'This book belongs entirely to the Prophecy Program, where Israel is God’s covenant nation with an earthly kingdom destiny (Ex. 19:5–6; Jer. 31:35–37).')]),
(2, 'Narrative Flow of 1 Chronicles', [('p', 'This section gives you a simple walkthrough of how the book unfolds. Instead of diving into details right away, it shows the major movements in the book — how its message begins, how it develops, and how it builds toward its close. Seeing the flow of the book helps you understand the big picture before you study the individual passages.'), ('h3', 'Movement 1 — Genealogies from Adam to the Post-Exilic Community (Chs. 1–9)'), ('p', 'The genealogies trace Israel’s identity from Adam through the tribes, showing God’s preservation of His covenant people (1 Chr. 1:1; 1 Chr. 9:1–2).'), ('h3', 'Movement 2 — Saul’s Fall and Theological Verdict (Ch. 10)'), ('p', 'Saul’s fall is attributed to his unfaithfulness and consulting a medium instead of seeking the LORD (1 Chr. 10:13–14).'), ('h3', 'Movement 3 — David’s Rise, Reign, and Military Victories (Chs. 11–20)'), ('p', 'David is anointed king, secures Jerusalem, brings the Ark, and defeats Israel’s enemies (1 Chr. 11:3; 1 Chr. 15:25–28; 1 Chr. 18:6).'), ('h3', 'Movement 4 — The Davidic Covenant (Ch. 17)'), ('p', 'God promises David an eternal throne, house, and kingdom (1 Chr. 17:11–14).'), ('h3', 'Movement 5 — Temple Preparation and National Organization (Chs. 21–29)'), ('p', 'David organizes Levites, priests, musicians, gatekeepers, and gives Solomon the Temple plans (1 Chr. 23:1–5; 1 Chr. 28:11–19). The book ends with David’s prayer, offerings, Solomon’s coronation, and David’s death (1 Chr. 29:10–22).')]),
(3, 'Program Themes in 1 Chronicles', [('p', 'This section highlights the major ideas emphasized in the book — the big doctrinal themes that shape how Israel should think and live under the covenants. These themes are not verse-by-verse explanations; they are the book’s main emphases, the repeated ideas God wants Israel to carry forward. Seeing these themes together helps you understand the book’s message before you look at the individual truths in the tables.'), ('ol', ['<b>Covenant Continuity</b> — God preserves Israel’s identity through exile, proving He remembers His covenant forever (1 Chr. 9:1; Ps. 105:8–10).', '<b>Davidic Kingship</b> — The eternal throne promised to David is the foundation of Israel’s kingdom hope (1 Chr. 17:12–14; Ps. 89:3–4).', '<b>Temple-Centered Worship</b> — Worship is ordered, Levitical, and central to Israel’s prophetic identity (1 Chr. 15:13–15; 1 Chr. 23:28–32).', '<b>National Accountability</b> — Saul’s death and David’s census show Israel’s leaders are accountable to God within the covenant framework (1 Chr. 10:13–14; 1 Chr. 21:7–14).', '<b>Prophetic Hope</b> — The book reinforces Israel’s expectation of a future kingdom ruled by David’s Son (Isa. 9:6–7; Jer. 23:5–6).'])]),
(4, 'Christ in 1 Chronicles', [('p', 'This section gathers what the book teaches about Christ — through foreshadowing, typology, and prophetic anticipation. These statements help you see the book’s Christ-centered trajectory before you study the doctrinal truths in detail. By collecting these points together, you get a clear picture of how 1 Chronicles points to Christ.'), ('ol', ['<b>The Son of David</b> — The Davidic covenant anticipates Christ as Israel’s promised King (Luke 1:32–33; Matt. 1:1).', '<b>The True Temple Builder</b> — Solomon builds the earthly Temple; Christ builds the greater Temple in the kingdom (1 Chr. 22:10; John 2:19–21).', '<b>The Perfect Worshiper</b> — David’s ordered worship anticipates Christ’s perfect obedience and leadership in Israel’s future kingdom (Ps. 40:7–8; Heb. 10:5–7).', '<b>The Messianic Shepherd-King</b> — David’s shepherd role foreshadows Christ as Israel’s Shepherd-King (1 Chr. 11:2; John 10:11).'])]),
(5, 'Israel, the Law, and the Covenants in 1 Chronicles', [('p', 'This section helps you see how 1 Chronicles speaks about Israel, the law, and the covenants without mixing programs. 1 Chronicles operates within Israel’s prophetic framework. By gathering these points together, this section shows you how to read 1 Chronicles in its own setting — as an Israel-program book — while recognizing what it says (and does not say) about the Body of Christ.'), ('p', '1 Chronicles reinforces Israel’s:'), ('ul', ['covenant nationhood', 'earthly kingdom destiny', 'Temple worship and Levitical order', 'Davidic monarchy', 'prophetic timeline']), ('p', 'All content belongs exclusively to the Prophecy Program.')]),
(6, 'Israel-Program Distinctions', [('p', 'This section highlights the teachings in 1 Chronicles that belong uniquely to Israel’s prophetic program — truths rooted in prophecy, covenant promises, national identity, and God’s dealings with Israel. By gathering these together, this section helps you see how 1 Chronicles contributes to Israel’s story without borrowing from the Body-of-Christ program.'), ('ul', ['Covenant Nationhood — Israel is God’s covenant people with a unique national identity (Ex. 19:5–6; 1 Chr. 1–9).', 'Davidic Covenant — God promises David an eternal throne, house, and kingdom (1 Chr. 17:11–14).', 'Earthly Kingdom Destiny — Israel’s future includes an earthly kingdom ruled by David’s Son (Luke 1:32–33; 1 Chr. 17).', 'Temple-Centered Worship — Worship is Levitical, sacrificial, and centered on the physical Temple (1 Chr. 23:28–32).', 'Levitical Priesthood — Only Levites serve in priestly functions; tribal roles are fixed (1 Chr. 24:1–19).', 'National Accountability — Israel’s leaders judged by covenant faithfulness (1 Chr. 10:13–14).', 'Prophetic Timeline — Israel awaits restoration and Messiah’s earthly reign (Acts 3:19–21).', 'National Worship Structure — Gatekeepers, musicians, singers, priests serve nationally (1 Chr. 16:4–6).', 'Sacrificial System — Burnt offerings and sacrifices belong to Israel’s covenant worship (1 Chr. 29:21).', 'Land Promises — Israel’s inheritance tied to the land (Deut. 30:5).'])]),
(7, 'Truths Table: What 1 Chronicles Says', [('p', 'This table gathers the key statements, instructions, and teachings in 1 Chronicles and shows which ones belong to Israel’s prophetic program. Each row lists a truth from the book, explains what it says, and identifies its program identity based on Israel’s covenant setting. This helps you see, at a glance, what 1 Chronicles teaches directly to Israel and keeps those truths separate from universal principles that apply more broadly.'), ('table', ['Category', 'Truth Revealed in 1 Chronicles', 'Program Identity', 'Scripture'], [['Covenant Nationhood', 'Israel is God’s covenant people with a unique national identity.', 'Israel / Kingdom / Prophecy Explicit Truth', 'Ex. 19:5–6; 1 Chr. 1–9'], ['Davidic Covenant', 'God promises David an eternal throne, house, and kingdom.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 17:11–14'], ['Earthly Kingdom Destiny', 'Israel’s future includes an earthly kingdom ruled by David’s Son.', 'Israel / Kingdom / Prophecy Explicit Truth', 'Luke 1:32–33; 1 Chr. 17'], ['Temple-Centered Worship', 'Worship is Levitical, sacrificial, and centered on the physical Temple.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 23:28–32'], ['Levitical Priesthood', 'Only Levites serve in priestly functions; tribal roles are fixed.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 24:1–19'], ['National Accountability', 'Israel’s leaders judged by covenant faithfulness.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 10:13–14'], ['Prophetic Timeline', 'Israel awaits restoration and Messiah’s earthly reign.', 'Israel / Kingdom / Prophecy Explicit Truth', 'Acts 3:19–21'], ['National Worship Structure', 'Gatekeepers, musicians, singers, priests serve nationally.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 16:4–6'], ['Sacrificial System', 'Burnt offerings and sacrifices belong to Israel’s covenant worship.', 'Israel / Kingdom / Prophecy Explicit Truth', '1 Chr. 29:21'], ['Land Promises', 'Israel’s inheritance tied to the land.', 'Israel / Kingdom / Prophecy Explicit Truth', 'Deut. 30:5']], [24, 41, 17, 18])]),
(8, 'Universal Truths Table (All People, All Time)', [('p', 'This table gathers the truths in 1 Chronicles that apply to everyone, not just Israel. These are principles rooted in God’s character — things that hold true across all programs and all ages. By separating these universal truths from Israel’s covenant-specific instructions, this section helps you see what 1 Chronicles teaches all believers everywhere and what it teaches Israel in its own setting.'), ('table', ['Universal Truth', 'Description', 'Scripture'], [['God’s Faithfulness', 'God keeps His word across generations.', 'Ps. 105:8'], ['Wholehearted Devotion', 'God calls all people to seek Him sincerely.', '1 Chr. 28:9'], ['God’s Holiness', 'God’s holiness demands reverence.', '1 Chr. 13:9–10'], ['Ordered Worship', 'God is worthy of intentional worship.', '1 Chr. 16:29'], ['Leadership Accountability', 'Leaders must walk faithfully.', '1 Chr. 10:13–14'], ['Diligence in God’s Work', 'God honors preparation and excellence.', '1 Chr. 22:5'], ['Bold Prayer', 'God hears sincere prayer.', '1 Chr. 29:10–19'], ['Humility and Repentance', 'God honors the humble heart.', '1 Chr. 21:16–17']], [30, 46, 24])]),
(9, 'Program-Safe Application Grid', [('p', 'This section shows how to apply the teachings of 1 Chronicles without mixing programs. The applications come from Israel’s covenant story and from universal truths that apply to everyone. By keeping the applications tied to what the book actually says — and not borrowing commands from Israel’s covenants for the Body of Christ — this grid helps you respond to 1 Chronicles in a way that is faithful to its setting, clear, and safe.'), ('ol', ['<b>Trust God’s faithfulness</b> — He keeps His word across generations.', '<b>Seek God wholeheartedly</b> — God desires sincere pursuit.', '<b>Honor God’s holiness</b> — Approach Him with reverence.', '<b>Value ordered worship</b> — Worship intentionally and thoughtfully.', '<b>Learn from leadership failures</b> — Faithfulness matters.', '<b>Prepare for God’s work</b> — Serve with diligence and excellence.', '<b>Pray boldly</b> — Approach God with confidence and gratitude.', '<b>Walk in humility</b> — Repentance restores fellowship.'])]),
(10, 'Teaching Outline for 1 Chronicles', [('p', 'This outline gives you a teacher-ready structure for presenting the book. It follows the narrative movements and highlights the major themes, making it easy to teach 1 Chronicles in classes, small groups, or personal study.'), ('olr', ['Israel’s Lineage Preserved (Chs. 1–9) — God preserves Israel’s covenant identity through genealogies from Adam to the post-exilic community. <i>(1 Chr. 1:1; 1 Chr. 9:1–2)</i>', 'Saul’s Fall and David’s Rise (Chs. 10–12) — Saul’s unfaithfulness leads to his downfall; David is established as God’s chosen king. <i>(1 Chr. 10:13–14; 1 Chr. 11:3)</i>', 'The Ark, Worship, and National Order (Chs. 13–16) — David restores proper worship, brings the Ark to Jerusalem, and establishes Levitical order. <i>(1 Chr. 13:9–10; 1 Chr. 15:25–28; 1 Chr. 16:4–36)</i>', 'The Davidic Covenant (Ch. 17) — God promises David an eternal house, throne, and kingdom, forming the foundation of Israel’s prophetic hope. <i>(1 Chr. 17:11–14)</i>', 'David’s Victories and Failures (Chs. 18–21) — David’s military triumphs expand Israel’s borders; his census brings judgment and mercy. <i>(1 Chr. 18:6; 1 Chr. 21:7–14)</i>', 'Temple Preparation and National Organization (Chs. 22–27) — David prepares materials, assigns Levites, priests, musicians, gatekeepers, and organizes national service for the future Temple. <i>(1 Chr. 22:5; 1 Chr. 23:28–32)</i>', 'David’s Final Charge, Prayer, and Solomon’s Coronation (Chs. 28–29) — David commissions Solomon, prays over the nation, leads offerings, and Israel anoints Solomon king. <i>(1 Chr. 28:9; 1 Chr. 29:10–22)</i>'])]),
(11, 'Companion Usage and Study Suggestions', [('h3', 'How to Use This Companion in Personal Study'), ('p', 'This Companion is designed to walk alongside you as you read 1 Chronicles, helping you see both the prophetic structure of the book and the timeless truths rooted in God’s character. Use it slowly, chapter by chapter, letting the narrative movements, themes, and universal truths deepen your understanding. The Program-Safe Applications will guide your heart toward devotion, worship, and humility without confusing Israel’s covenant commands with the Body of Christ’s calling today.'), ('h3', 'How to Use This Companion in Small Groups or Classes'), ('p', 'This Companion provides a clear, structured framework that makes teaching 1 Chronicles simple and accessible. Each section gives you ready-to-use material: narrative movements for overview, prophecy-program themes for doctrinal clarity, universal truths for discussion, and a pastoral teaching outline for weekly lessons. Use the tables to help your group distinguish Israel’s covenant identity from universal principles, and use the Program-Safe Application Grid to foster meaningful, Christ-centered conversation.'), ('h3', 'How This Companion Fits Within the Acts Overlap Theology Series'), ('p', 'This Companion is part of a larger series designed to help believers read every book of Scripture without blurring God’s prophetic program for Israel and His mystery program for the Body of Christ. Within the Acts Overlap framework, 1 Chronicles stands firmly in Israel’s covenant story, yet it still reveals universal truths that shape Christian character today. This Companion shows you how to honor the book’s prophetic context while drawing out the timeless principles that apply to all believers in every age.')])]

# Place in God's Storyline (Master Standard v1.155): last item of Section 1
from storyline import S as _STORY
SECTIONS[0][2].append(('p', '<b>Place in God’s Storyline.</b> ' + _STORY['1chr'][1]))
